const dialog=document.querySelector('#certificate-dialog');
document.querySelectorAll('[data-certificate]').forEach(button=>button.addEventListener('click',()=>{const img=document.querySelector('#certificate-full');img.src=button.dataset.certificate;img.alt=button.dataset.title;document.querySelector('#certificate-title').textContent=button.dataset.title;document.querySelector('#certificate-original').href=button.dataset.certificate;dialog.showModal();document.documentElement.classList.add('modal-open')}));
document.querySelector('#close-certificate').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.documentElement.classList.remove('modal-open'));dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.section-head,.services article,.gallery figure,.certificate-card,.process article,.brand-card,.review-form').forEach(el=>{el.classList.add('reveal-pending');observer.observe(el)});const bar=document.createElement('div');bar.className='scroll-progress';bar.setAttribute('aria-hidden','true');document.body.append(bar);let scheduled=false;function update(){const max=document.documentElement.scrollHeight-innerHeight;bar.style.width=(max>0?scrollY/max*100:0)+'%';scheduled=false}addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(update)}},{passive:true});addEventListener('resize',update);update()}
